const DAYNAMES = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];
/* spelled out, for anywhere the coach says the day rather than labels it */
const DAY_FULL = ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"];
const stepBtn = {
  width: 34, height: 34, borderRadius: 9, cursor: "pointer", fontSize: 16,
  border: "1.5px solid #F0E4E7", background: "transparent", color: "#8A7885",
};
const SCOPE_LABEL = { day: "today", week: "this week", month: "this month", quarter: "so far", year: "the year" };
const DAY_KEYS = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];
const iso = (d) => d.toLocaleDateString("en-CA");
const today = () => iso(new Date());
const parse = (s) => { const [y, m, d] = s.split("-").map(Number); return new Date(y, m - 1, d); };
const addDays = (s, n) => { const d = parse(s); d.setDate(d.getDate() + n); return iso(d); };
/* Her week runs Sunday → Saturday. */
const WEEK_STARTS_ON = 6;   /* Saturday — hers, and her WHOOP day */
const weekStartOn = (settings) => {
  const v = Number(settings && settings.weekStartsOn);
  return Number.isInteger(v) && v >= 0 && v <= 6 ? v : WEEK_STARTS_ON;
};
/* the second argument is the weekday her week begins on. Left off it is the
   APP default, not her setting — so pass it (audit item 22). */
const weekStart = (s, startOn) => {
  const on = Number.isInteger(startOn) ? startOn : WEEK_STARTS_ON;
  const d = parse(s);
  d.setDate(d.getDate() - ((d.getDay() - on + 7) % 7));
  return iso(d);
};
const monthKey = (s) => s.slice(0, 7);
const prettyShort = (d) =>
  parse(d).toLocaleDateString(undefined, { weekday: "long" }).toLowerCase();

const dayName = (s) => DAY_KEYS[parse(s).getDay()];
const prettyDate = (s) => parse(s).toLocaleDateString(undefined, { weekday: "long", day: "numeric", month: "long" });
/* A day and a month, for anything far enough back that a weekday name alone
   would be ambiguous. */
const dayAndMonth = (s) => parse(s).toLocaleDateString(undefined, { day: "numeric", month: "short" });

